const failingProvider = (reason: unknown): AIProvider => ({
  sendMessage: () => ({
    [Symbol.asyncIterator]: () => ({next: () => Promise.reject(reason)}),
  }),
  generateStructured: () => Promise.resolve({} as never),
});

