  const causes: unknown[] = [];
  const orchestrator = createChatOrchestrator(
    failingProvider(reason),
    new PromptBuilder({identity: 'You are a test assistant.'}),
    undefined,
    {
      hooks: {
        onError: async (_session, error) => {
          causes.push(error.cause);
        },
      },
    }
  );
  const session = {
    sessionId: 's',
    userId: 'u',
    entries: [{role: 'user' as const, content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  await orchestrator.processMessage(session).catch(() => undefined);
  return causes;
};

